{
  "template": "trigger"
}

namespace flow;
table Settings { seed:ulong; layers:ulong; width:ulong; edge_probability:double; max_capacity:ulong; }
table Outputs { settings:Settings (required); }
root_type Outputs;

{
  "template": "input",
  "params": [
    {
      "name": "seed",
      "type": "uint64",
      "data": 53
    },
    {
      "name": "layers",
      "type": "uint64",
      "data": 3
    },
    {
      "name": "width",
      "type": "uint64",
      "data": 3
    },
    {
      "name": "edge_probability",
      "type": "double",
      "data": 0.6
    },
    {
      "name": "max_capacity",
      "type": "uint64",
      "data": 20
    }
  ]
}

namespace flow;
table Network {
  nodes:string;
  tail:[ulong];
  head:[ulong];
  capacity:[ulong];
}
table Outputs { network:Network (required); }
root_type Outputs;

{ pkgs, inputs, params }:
let
  sdk = inputs.tsugumi.sdk { languages = [ "python" ]; };
in
{
  run = inputs.tsugumi.pythonCard {
    inherit sdk;
    src = ./src;
    packages = ps: [ ps.numpy ];
  };
}

{
  "language": "python",
  "inputs": [
    {
      "name": "settings"
    }
  ]
}

